//! Pure-Rust host launchers with the exact `candle-kernels/src/ffi.rs` signatures of candle's MoE C
//! launchers (`moe_gemm_wmma`, `moe_gemm_gguf`, `moe_gemm_gguf_prefill`), launching the cuda-oxide
//! kernels of this crate on the caller's stream through the CUDA driver API.
//!
//! Reproduced host logic (moe_wmma.cu / moe_gguf.cu / moe_wmma_gguf.cu / moe_utils.cuh):
//! - offsets: memset(counts) -> count_tokens_per_expert (grid ceil(m/256), block 256) -> scan.
//!   The reference scans with thrust::inclusive_scan (prefill) or `expert_prefix_sum_kernel`
//!   (decode, one block of max(num_experts, 32) <= 1024 threads); both are replaced by
//!   `moe_expert_offsets` (same integers). A decode launch with num_experts > 1024 is an invalid
//!   CUDA launch in the reference (offsets left untouched); mirrored by skipping the scan.
//! - `moe_gemm_gguf`: cudaMallocAsync'd Q8_1 buffer (m = topk_weights ? size_m : size_m / topk rows
//!   of pad(k, 512)), quantize_q8_1 grid (ceil(kx_padded/256), m), GEMV grid (ceil(n/4), size_m),
//!   block (32, 4), shared size_k/qk*sizeof(block)*4 + 1024, then cudaFreeAsync.
//! - `moe_gemm_gguf_prefill`: cudaMallocAsync'd counts/offsets, the thrust-path offsets, grid
//!   (num_experts, ceil(n/32)), block (32|64, 4), shared A + B + Bq + C, then cudaFreeAsync.
//! - The reference objects are compiled with `--default-stream per-thread`: stream 0 means the
//!   per-thread default stream (`CU_STREAM_PER_THREAD`), not the legacy stream.
//! - A launch with a zero grid dimension fails in the reference and does nothing; skipped here.
//!
//! The oxide PTX is loaded once per CUDA context (embedded bundle of this executable, else
//! `$CANDLE_MOE_PTX`, else `candle_moe.ptx` next to Cargo.toml).
use crate::cu;
use std::collections::HashMap;
use std::ffi::c_void;
use std::sync::Mutex;

const CU_STREAM_PER_THREAD: usize = 0x2;

struct Module {
    module: cu::CUmodule,
    funcs: HashMap<&'static str, cu::CUfunction>,
}
unsafe impl Send for Module {}

static MODULES: Mutex<Option<HashMap<usize, Module>>> = Mutex::new(None);

fn ptx_source() -> &'static [u8] {
    crate::image::candle_moe()
}

fn check(r: cu::CUresult, what: &str) {
    if r != cu::cudaError_enum_CUDA_SUCCESS {
        panic!("candle-moe: {what} failed: {r:?}");
    }
}

fn cu_stream(stream: i64) -> cu::CUstream {
    if stream == 0 { CU_STREAM_PER_THREAD as cu::CUstream } else { stream as usize as cu::CUstream }
}

/// The function `name` in this crate's module for the context owning `stream`.
unsafe fn function(stream: cu::CUstream, name: &'static str) -> cu::CUfunction {
    let mut ctx: cu::CUcontext = std::ptr::null_mut();
    if stream as usize != CU_STREAM_PER_THREAD {
        check(cu::cuStreamGetCtx(stream, &mut ctx), "cuStreamGetCtx");
    }
    if ctx.is_null() {
        check(cu::cuCtxGetCurrent(&mut ctx), "cuCtxGetCurrent");
    }
    let mut guard = MODULES.lock().unwrap();
    let map = guard.get_or_insert_with(HashMap::new);
    let m = map.entry(ctx as usize).or_insert_with(|| {
        let src = ptx_source();
        let mut module: cu::CUmodule = std::ptr::null_mut();
        check(cu::cuCtxPushCurrent_v2(ctx), "cuCtxPushCurrent");
        check(cu::cuModuleLoadData(&mut module, src.as_ptr() as *const c_void), "cuModuleLoadData(candle-moe PTX)");
        let mut popped: cu::CUcontext = std::ptr::null_mut();
        check(cu::cuCtxPopCurrent_v2(&mut popped), "cuCtxPopCurrent");
        Module { module, funcs: HashMap::new() }
    });
    let module = m.module;
    *m.funcs.entry(name).or_insert_with(|| {
        let mut f: cu::CUfunction = std::ptr::null_mut();
        let cname = std::ffi::CString::new(name).unwrap();
        check(cu::cuModuleGetFunction(&mut f, module, cname.as_ptr()), name);
        f
    })
}

/// A kernel argument list: each value is stored in its own 8-byte slot.
struct Args(Vec<[u8; 8]>);
impl Args {
    fn new() -> Self {
        Args(Vec::new())
    }
    fn p<T>(mut self, v: *const T) -> Self {
        self.0.push((v as u64).to_le_bytes());
        self
    }
    fn i(mut self, v: i32) -> Self {
        self.0.push((v as u32 as u64).to_le_bytes());
        self
    }
}

unsafe fn launch(stream: cu::CUstream, name: &'static str, grid: (u32, u32, u32), block: (u32, u32, u32), shared: u32, args: Args) {
    if grid.0 == 0 || grid.1 == 0 || grid.2 == 0 {
        return; // the reference's launch fails with cudaErrorInvalidConfiguration: nothing runs
    }
    let f = function(stream, name);
    let mut slots = args.0;
    let mut ptrs: Vec<*mut c_void> = slots.iter_mut().map(|s| s.as_mut_ptr() as *mut c_void).collect();
    check(
        cu::cuLaunchKernel(f, grid.0, grid.1, grid.2, block.0, block.1, block.2, shared, stream, ptrs.as_mut_ptr(), std::ptr::null_mut()),
        name,
    );
}

unsafe fn memset0(stream: cu::CUstream, p: *mut i32, count: usize) {
    if count > 0 {
        check(cu::cuMemsetD32Async(p as u64, 0, count, stream), "cuMemsetD32Async");
    }
}

/// count_tokens_per_expert + exclusive scan into offsets[0..=num_experts]; `light` is the decode
/// path (`calculate_expert_offsets_light`).
unsafe fn compute_offsets(stream: cu::CUstream, expert_ids: *const i32, size_m: i32, counts: *mut i32, offsets: *mut i32, num_experts: i32, light: bool) {
    memset0(stream, counts, num_experts.max(0) as usize);
    let blocks = (size_m + 255) / 256;
    launch(stream, "moe_count_tokens", (blocks.max(0) as u32, 1, 1), (256, 1, 1), 0,
           Args::new().p(expert_ids).p(counts).i(size_m));
    if light && num_experts > 1024 {
        return; // expert_prefix_sum_kernel<<<1, num_experts>>> is an invalid launch
    }
    if num_experts <= 0 {
        if !light && num_experts == 0 {
            // thrust scans nothing; offsets[0] = 0 by the memset
            memset0(stream, offsets, 1);
        }
        return;
    }
    launch(stream, "moe_expert_offsets", (1, 1, 1), (1024, 1, 1), 0, Args::new().p(counts).p(offsets).i(num_experts));
}

/// `moe_gemm_wmma` (moe_wmma.cu).
