/// (qk, sizeof(block)) for gguf types 0..5.
fn gguf_block(t: i32) -> Option<(i32, i32)> {
    Some(match t {
        0 => (32, 34),
        1 => (256, 144),
        2 => (256, 84),
        3 => (256, 110),
        4 => (256, 176),
        5 => (256, 210),
        _ => return None,
    })
}

/// `moe_gemm_gguf` (moe_gguf.cu), decode.
#[allow(clippy::too_many_arguments)]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn moe_gemm_gguf(
    input: *const f32,
    weights: *const c_void,
    sorted_token_ids: *const i32,
    expert_ids: *const i32,
    topk_weights: *const f32,
    output: *mut c_void,
    num_experts: i32,
    topk: i32,
    size_m: i32,
    size_n: i32,
    size_k: i32,
    gguf_dtype: i32,
    stream: i64,
) {
    let s = cu_stream(stream);
    let kx_padded = (size_k + 511) / 512 * 512;
    let num_blocks = (kx_padded + 255) / 256;
    let m = if topk_weights.is_null() { size_m / topk } else { size_m };
    let y_bytes = m.wrapping_mul(kx_padded / 32 * 36);
    let mut y: cu::CUdeviceptr = 0;
    if y_bytes > 0 {
        check(cu::cuMemAllocAsync(&mut y, y_bytes as i64 as u64 as usize, s), "cuMemAllocAsync");
    }
    launch(s, "moe_quantize_q8_1", (num_blocks as u32, m as u32, 1), (256, 1, 1), 0,
           Args::new().p(input).p(y as *const u8).i(size_k).i(kx_padded));
    if let Some((qk, bs)) = gguf_block(gguf_dtype) {
        let n_wraps = 4;
        let shared = size_k / qk * bs * n_wraps + 1024;
        let name = ["moe_gguf_q8_0", "moe_gguf_q4_k", "moe_gguf_q2_k", "moe_gguf_q3_k", "moe_gguf_q5_k", "moe_gguf_q6_k"][gguf_dtype as usize];
        launch(s, name, (((size_n + n_wraps - 1) / n_wraps) as u32, size_m as u32, 1), (32, n_wraps as u32, 1), shared as u32,
               Args::new().p(weights).p(y as *const u8).p(sorted_token_ids).p(expert_ids).p(topk_weights).p(output)
                   .i(num_experts).i(topk).i(size_m).i(size_n).i(size_k).i(kx_padded));
    }
    if y != 0 {
        check(cu::cuMemFreeAsync(y, s), "cuMemFreeAsync");
    }
}

/// `moe_gemm_gguf_prefill` (moe_wmma_gguf.cu).
#[allow(clippy::too_many_arguments)]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn moe_gemm_gguf_prefill(
    input: *const c_void,
    weights: *const u8,
    sorted_token_ids: *const i32,
    expert_ids: *const i32,
    topk_weights: *const f32,
    output: *mut c_void,
    num_experts: i32,
    topk: i32,
    size_m: i32,
    size_n: i32,
    size_k: i32,
    input_dtype: i32,
    gguf_dtype: i32,
    stream: i64,
) {
    let s = cu_stream(stream);
    let mut counts: cu::CUdeviceptr = 0;
    let mut offsets: cu::CUdeviceptr = 0;
    let ne = num_experts.max(0) as usize;
    if ne > 0 {
        check(cu::cuMemAllocAsync(&mut counts, ne * 4, s), "cuMemAllocAsync");
    }
    check(cu::cuMemAllocAsync(&mut offsets, (ne + 1) * 4, s), "cuMemAllocAsync");
    compute_offsets(s, expert_ids, size_m, counts as *mut i32, offsets as *mut i32, num_experts, false);
    if let Some((qk, bs)) = gguf_block(gguf_dtype) {
        let a = 32 * qk * 2;
        let smem = (2 * a + 32 * bs + 3) / 4 * 4 + 32 * 32 * 4;
        let wrap = if gguf_dtype == 0 || gguf_dtype == 1 { 32 } else { 64 };
        let tn = ["q8_0", "q4_k", "q2_k", "q3_k", "q5_k", "q6_k"][gguf_dtype as usize];
        let name: &'static str = match (input_dtype == 0, tn) {
            (true, "q8_0") => "moe_gguf_prefill_f16_q8_0",
            (true, "q4_k") => "moe_gguf_prefill_f16_q4_k",
            (true, "q2_k") => "moe_gguf_prefill_f16_q2_k",
            (true, "q3_k") => "moe_gguf_prefill_f16_q3_k",
            (true, "q5_k") => "moe_gguf_prefill_f16_q5_k",
            (true, _) => "moe_gguf_prefill_f16_q6_k",
            (false, "q8_0") => "moe_gguf_prefill_bf16_q8_0",
            (false, "q4_k") => "moe_gguf_prefill_bf16_q4_k",
            (false, "q2_k") => "moe_gguf_prefill_bf16_q2_k",
            (false, "q3_k") => "moe_gguf_prefill_bf16_q3_k",
            (false, "q5_k") => "moe_gguf_prefill_bf16_q5_k",
            (false, _) => "moe_gguf_prefill_bf16_q6_k",
        };
        launch(s, name, (num_experts as u32, ((size_n + 31) / 32) as u32, 1), (wrap, 4, 1), smem as u32,
               Args::new().p(input).p(weights).p(sorted_token_ids).p(offsets as *const i32).p(topk_weights).p(output)
                   .i(num_experts).i(topk).i(size_m).i(size_n).i(size_k));
    }
    if counts != 0 {
        check(cu::cuMemFreeAsync(counts, s), "cuMemFreeAsync");
    }
    check(cu::cuMemFreeAsync(offsets, s), "cuMemFreeAsync");
}
